      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A fonte apenas sinaliza, em nível resumido, que parte da água produzida tratada pode ser reciclada em reinjeção secundária, sem conteúdo suficiente sobre sistemas de água doce, potável e de serviço.",
          "trechos": [
            "E1da8b8da8efbd574:1399:2098",
            "E1da8b8da8efbd574:2098:2334"
          ],
          "condicoes": [
            "após tratamento da água produzida"
          ],
          "limites": [
            "trecho resumido e incompleto",
            "não descreve tecnologias ou critérios do recorte"
          ]
        }
      ]
    }
